// Exact Windows profiles compiled directly into the BOF.

#[repr(usize)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum KernelField {
    PeTimestamp = 0,
    PeChecksum = 1,
    ImageSize = 2,
    PdbGuidA = 3,
    PdbGuidB = 4,
    PdbGuidC = 5,
    PdbGuidDLow = 6,
    PdbGuidDHigh = 7,
    PdbAge = 8,
    PsInitialSystemProcessRva = 9,
    ProcessCallbackArrayRva = 10,
    ThreadCallbackArrayRva = 11,
    ImageCallbackArrayRva = 12,
    EtwTiHandleRva = 13,
    RegistryCallbackListRva = 14,
    PsProcessTypeRva = 15,
    PsThreadTypeRva = 16,
    EtwRegEntrySize = 17,
    EtwRegGuidEntry = 18,
    EtwRegEnableMask = 19,
    EtwGuidEntrySize = 20,
    EtwGuidProviderEnableInfo = 21,
    TraceEnableIsEnabled = 22,
    TraceEnableLevel = 23,
    TraceEnableProperty = 24,
    TraceEnableMatchAny = 25,
    TraceEnableMatchAll = 26,
    ObjectTypeSize = 27,
    ObjectTypeKey = 28,
    ObjectTypeCallbackList = 29,
    EprocessPcb = 30,
    EprocessPid = 31,
    EprocessLinks = 32,
    EprocessToken = 33,
    EprocessSectionBase = 34,
    EprocessPeb = 35,
    EprocessImage = 36,
    EprocessAuditImage = 37,
    EprocessSignatureLevel = 38,
    EprocessSectionSignatureLevel = 39,
    EprocessProtection = 40,
    EprocessVadRoot = 41,
    KprocessDirectoryTableBase = 42,
    TokenId = 43,
    TokenAuthenticationId = 44,
    TokenPrivilegesPresent = 45,
    TokenPrivilegesEnabled = 46,
    TokenPrivilegesDefault = 47,
    TokenSessionId = 48,
    TokenUserGroupCount = 49,
    TokenRestrictedSidCount = 50,
    TokenDefaultOwnerIndex = 51,
    TokenUserGroups = 52,
    TokenType = 53,
    TokenImpersonationLevel = 54,
    TokenFlags = 55,
    TokenInUse = 56,
    TokenIntegrityIndex = 57,
    TokenMandatoryPolicy = 58,
    SidAndAttributesSize = 59,
    SidAndAttributesSid = 60,
    SidAndAttributesAttributes = 61,
}

#[derive(Clone, Copy)]
pub struct KernelProfile {
    pub id: &'static str,
    pub display_build: &'static str,
    values: [u32; 62],
}

impl KernelProfile {
    pub const fn value(&self, field: KernelField) -> u32 {
        self.values[field as usize]
    }
}

