#[derive(Clone, Copy)]
pub struct CredentialComponent {
    pub package: &'static str,
    pub name: &'static str,
    pub sha256: &'static str,
    pub size_bytes: u64,
    pub pe_timestamp: u32,
    pub pe_checksum: u32,
    pub image_size: u32,
    pub pdb_guid: &'static str,
    pub pdb_age: u32,
    pub root_symbol: &'static str,
    pub root_rva: u32,
}

#[derive(Clone, Copy)]
pub struct CredentialProfile {
    pub id: &'static str,
    pub build: u32,
    pub lsasrv: CredentialImage,
    pub wdigest: CredentialImage,
    pub wdigest_list_rva: u32,
    pub components: &'static [CredentialComponent],
    pub expected_absent: &'static [&'static str],
}

#[derive(Clone, Copy)]
pub struct CredentialImage {
    pub name: &'static str,
    pub pe_timestamp: u32,
    pub pe_checksum: u32,
    pub image_size: u32,
}

